package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import android.view.*;
final class SeasonalOverlay extends View {
 final Paint pen=new Paint(3);String kind="off";boolean motion=true,active=false;float phase=0;long last=0;final float density;
 final Runnable tick=new Runnable(){public void run(){if(active&&motion&&!kind.equals("off")&&isShown()&&getWindowVisibility()==VISIBLE){invalidate();postDelayed(this,67);}}};
 SeasonalOverlay(Context c){super(c);density=getResources().getDisplayMetrics().density;setClickable(false);setLongClickable(false);setFocusable(false);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
 void configure(String effect,boolean moving){kind=effect;motion=moving;setVisibility(kind.equals("off")?GONE:VISIBLE);restart();invalidate();}
 void running(boolean running){active=running;last=SystemClock.elapsedRealtime();restart();}
 void restart(){removeCallbacks(tick);if(active&&motion&&!kind.equals("off")&&getVisibility()==VISIBLE&&getWindowVisibility()==VISIBLE)post(tick);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();restart();}
 @Override protected void onDetachedFromWindow(){removeCallbacks(tick);super.onDetachedFromWindow();}
 @Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);last=SystemClock.elapsedRealtime();restart();}
 @Override public boolean onTouchEvent(MotionEvent event){return false;}
 @Override protected void onDraw(Canvas c){if(kind.equals("off")||getWidth()==0||getHeight()==0)return;long now=SystemClock.elapsedRealtime();if(active&&motion&&last>0)phase+=Math.min(.12f,(now-last)/1000f);last=now;float t=motion?phase:0,w=getWidth(),h=getHeight();pen.setStyle(Paint.Style.FILL);for(int i=0;i<28;i++){float speed=kind.equals("rain")?92:kind.equals("leaves")?24:18;float x=((i*73%997)/997f*w+(float)Math.sin(t*.45+i)*18*density+w)%w;float y=((i*137%991)/991f*(h+40*density)+t*speed*density)%(h+40*density)-20*density;float r=(2+i%3)*density;if(kind.equals("rain")){pen.setColor(0xff4277a5);pen.setAlpha(55);pen.setStrokeWidth(density);c.drawLine(x,y,x-3*density,y+13*density,pen);}else if(kind.equals("leaves")||kind.equals("petals")){pen.setColor(kind.equals("leaves")?(i%2==0?0xffbd662f:0xff8a622e):(i%2==0?0xffc87796:0xff9a789e));pen.setAlpha(65);c.save();c.rotate(i*23+t*25,x,y);c.drawOval(new RectF(x-r,y-2*r,x+r,y+2*r),pen);pen.setStrokeWidth(density*.6f);c.drawLine(x,y-2*r,x,y+3*r,pen);c.restore();}else if(kind.equals("confetti")){int[] colors={0xffb75a76,0xffb5872a,0xff477c62,0xff5878a7};pen.setColor(colors[i%4]);pen.setAlpha(65);c.save();c.rotate(i*31+t*35,x,y);c.drawRect(x-r,y-r,x+r,y+2*r,pen);c.restore();}else if(kind.equals("sparkles")){pen.setColor(0xff987b32);pen.setAlpha(45+(int)(20*Math.sin(t+i)));pen.setStrokeWidth(density);c.drawLine(x-r,y,x+r,y,pen);c.drawLine(x,y-r,x,y+r,pen);}else{pen.setColor(0xff7295b2);pen.setAlpha(60);c.drawCircle(x,y,r*.6f,pen);}}if(kind.equals("snowmen")){float size=Math.min(26*density,h*.055f);snowman(c,w*.075f,h-8*density,size);snowman(c,w*.925f,h-8*density,size*.8f);}}
 void snowman(Canvas c,float x,float bottom,float r){pen.setStyle(Paint.Style.FILL);pen.setColor(0xffa9c4d8);pen.setAlpha(95);c.drawCircle(x,bottom-r,r,pen);c.drawCircle(x,bottom-r*2.45f,r*.7f,pen);pen.setColor(0xff34536d);pen.setAlpha(105);c.drawRect(x-r*.75f,bottom-r*3.12f,x+r*.75f,bottom-r*2.94f,pen);c.drawRect(x-r*.48f,bottom-r*3.7f,x+r*.48f,bottom-r*3.03f,pen);c.drawCircle(x-r*.22f,bottom-r*2.52f,r*.07f,pen);c.drawCircle(x+r*.22f,bottom-r*2.52f,r*.07f,pen);pen.setColor(0xffbd7842);pen.setAlpha(120);Path nose=new Path();nose.moveTo(x,bottom-r*2.38f);nose.lineTo(x+r*.65f,bottom-r*2.28f);nose.lineTo(x,bottom-r*2.2f);nose.close();c.drawPath(nose,pen);pen.setColor(0xffa95c64);pen.setAlpha(100);c.drawRect(x-r*.6f,bottom-r*1.98f,x+r*.6f,bottom-r*1.78f,pen);}
}
